cd "C:\Users\Aaron Karacas\aura-worker\aura\aura-workers\aura-core"
# THE INKIT.WORLD SCREENS - every picture the new pages need (2026-10-23, Aaron: "run all the pictures").
# Same recipe as the approved What's Trending banner (img_mvln63bgednn): the catalogue model, the exact size, the words only.
# No words are ever drawn into a picture - every title on these screens is page text. Where text sits on a picture,
# that side is drawn dark and empty. One at a time; each line prints its name and its address.
$jobs = @(
  # ── HOME BANNERS (2048x864, words on the left) ─────────────────────────────────────────────
  @{ n="home_styles"; w=2048; h=864; s="A wide cinematic photograph for a website banner. On the right, a vivid neo-traditional tattoo of a roaring tiger framed by red roses and a colorful butterfly, healed on a tanned upper arm and shoulder, rich saturated color, warm studio light with a soft purple glow. The left half of the picture is dark and empty, fading to near black, with nothing in it. No text, no letters, no logos anywhere." },
  @{ n="home_beyond"; w=2048; h=864; s="A wide cinematic photograph for a website banner. On the right, an imaginative tattoo artwork of a woman's face in profile made of a starry cosmic galaxy in purple, blue and orange, with a glowing blue butterfly and bursts of light, rich and dreamlike. The left half of the picture is dark and empty, fading to near black, with nothing in it. No text, no letters, no logos anywhere." },
  # ── SCREEN BANNERS (2048x864, words on the left) ───────────────────────────────────────────
  @{ n="seeit_start"; w=2048; h=864; s="A wide cinematic photograph for a website banner. On the right, a detailed black-and-grey flower tattoo drawing of a large peony with leaves on paper, a tattoo pen resting on it, lit by a soft purple neon glow. The left half of the picture is dark and empty, fading to near black, with nothing in it. No text, no letters, no logos anywhere." },
  @{ n="inspired_imagine"; w=2048; h=864; s="A wide cinematic photograph for a website banner. On the right, a dreamy illustrated tattoo artwork of a woman in profile surrounded by pink and orange flowers, a purple butterfly, a crescent moon and mountains reflected in a lake at dusk, soft purple and orange light. The left half of the picture is dark and empty, fading to near black, with nothing in it. No text, no letters, no logos anywhere." },
  # ── SCREEN HEROES (2048x1056, words on the left) ───────────────────────────────────────────
  @{ n="hero_trending"; w=2048; h=1056; s="A wide cinematic photograph. On the right, a woman with sunglasses and her hair up, seen over her shoulder at a beach at sunset with palm trees, her shoulder and upper back covered in a healed black-and-grey tattoo of hibiscus flowers and a butterfly with soft peach shading. Warm orange and purple sunset light. The left half of the picture is darker and calm, with nothing in it. No text, no letters, no logos anywhere." },
  @{ n="hero_styles"; w=2048; h=1056; s="A wide cinematic photograph. On the right, a man with curly dark hair, stubble and sunglasses sitting outdoors in warm evening light, his upper arm and shoulder covered in a healed black-and-grey realism tattoo of a lion with a clock. Moody, rich tones. The left half of the picture is darker and calm, with nothing in it. No text, no letters, no logos anywhere." },
  @{ n="hero_create"; w=2048; h=1056; s="A wide cinematic photograph in a warm tattoo studio with framed flash art on the wall. On the right, a woman with dark hair looking down over her shoulder, her shoulder and upper back covered in a healed black-and-grey tattoo of peonies and a butterfly. Warm, moody light. The left half of the picture is darker and calm, with nothing in it. No text, no letters, no logos anywhere." },
  @{ n="hero_inspired"; w=2048; h=1056; s="A wide image of a fanned collage of phone screens and tattoo photos glowing with purple light: a lion with a crown, a red koi fish, a woman's face with flowers, a mountain landscape, a compass, a traditional tiger with red flowers, butterflies and flower sketches. Everything is on the right side. The left half of the picture is dark and empty, with nothing in it. No text, no letters, no logos anywhere." },
  @{ n="hero_build"; w=2048; h=1056; s="A wide cinematic photograph of two forearms side by side on the right side of the picture: the first forearm has one small black-and-grey rose tattoo, the second forearm shows that same rose grown into a fuller black-and-grey sleeve of roses, leaves and small flowers. Dark, moody background. The left half of the picture is dark and empty, with nothing in it. No text, no letters, no logos anywhere." },
  @{ n="hero_cover"; w=2048; h=1056; s="A wide cinematic photograph of two forearms side by side on the right side of the picture: the first forearm has an old faded red heart tattoo with blurry dotted outlines, the second forearm has a beautiful dense black-and-grey rose tattoo that completely covers where the heart was. Dark, moody background. The left half of the picture is dark and empty, with nothing in it. No text, no letters, no logos anywhere." },
  # ── INK IT EXAMPLES (photo, then the tattoo made from it) ─────────────────────────────────
  @{ n="inkit_1_photo"; w=1024; h=1024; s="A happy candid photo of a smiling woman with sunglasses hugging her golden retriever on a sunny beach. No text, no letters, no logos anywhere." },
  @{ n="inkit_1_tattoo"; w=1024; h=1536; s="A healed black-and-grey realism tattoo on a forearm of a smiling woman with sunglasses hugging her golden retriever, with a small heart, photographed close up in soft light. No text, no letters, no logos anywhere." },
  @{ n="inkit_2_photo"; w=1024; h=1024; s="A photo of a mountain lake at sunset with pine trees, glowing orange and purple sky reflected in the water. No text, no letters, no logos anywhere." },
  @{ n="inkit_2_tattoo"; w=1024; h=1536; s="A healed black-and-grey tattoo on a forearm of a mountain lake with pine trees and their reflection in the water, fine detailed shading, photographed close up in soft light. No text, no letters, no logos anywhere." },
  @{ n="inkit_3_photo"; w=1024; h=1024; s="A photo of a laughing toddler with curly brown hair in a white t-shirt, warm indoor light. No text, no letters, no logos anywhere." },
  @{ n="inkit_3_tattoo"; w=1024; h=1536; s="A healed black-and-grey realism portrait tattoo on a forearm of a laughing toddler with curly hair, with a small heart below, photographed close up in soft light. No text, no letters, no logos anywhere." },
  @{ n="inkit_4_photo"; w=1024; h=1024; s="A photo of a tabby cat with green eyes lying on a soft blanket, looking at the camera. No text, no letters, no logos anywhere." },
  @{ n="inkit_4_tattoo"; w=1024; h=1536; s="A healed black-and-grey realism tattoo on a forearm of a tabby cat face with bright green eyes, with a small heart below, photographed close up in soft light. No text, no letters, no logos anywhere." },
  # ── CARD PICTURES (1536x1024) ─────────────────────────────────────────────────────────────
  @{ n="build_take"; w=1536; h=1024; s="A hand holding a phone, taking a photo of a black-and-grey rose tattoo on a forearm; the phone screen shows the tattoo inside the camera frame. Warm blurred lights behind. No text, no letters, no logos anywhere." },
  @{ n="build_choose"; w=1536; h=1024; s="A fanned stack of photos of tattoos on arms - a black-and-grey rose, a mandala, flowers, a compass - with the rose photo in front, lit by a soft purple glow on a dark background. No text, no letters, no logos anywhere." },
  @{ n="build_idea"; w=1536; h=1024; s="An open spiral sketchbook with a pencil drawing of a large rose with leaves and a pen resting on it, next to a forearm with a small black-and-grey rose tattoo, warm light on a dark wooden table. No text, no letters, no logos anywhere." },
  @{ n="cover_take"; w=1536; h=1024; s="A hand holding a phone, taking a photo of an old faded red heart tattoo on a forearm; the phone screen shows the heart inside the camera frame. Warm blurred lights behind. No text, no letters, no logos anywhere." },
  @{ n="cover_choose"; w=1536; h=1024; s="A fanned stack of photos of old faded tattoos on skin - a red heart, a blurry name script, a faded koi - with the heart photo in front, lit by a soft purple glow on a dark background. No text, no letters, no logos anywhere." },
  @{ n="seeit_showme"; w=1024; h=1024; s="A phone showing a photo of an arm with a rose tattoo, surrounded by tattoo sketches of a butterfly and flowers and a sunset photo, glowing with soft purple light on a dark background. No text, no letters, no logos anywhere." }
)
$i = 0; $t0 = Get-Date; $done = @(); $bad = @()
foreach ($j in $jobs) { $i++
  $body = @{ subject = $j.s; model = "gpt-image-2"; width = $j.w; height = $j.h; exact_size = $true; raw = $true } | ConvertTo-Json -Compress
  $o = $null; try { $o = ((RUN ("SHOW_IT " + $body) | Out-String) | ConvertFrom-Json).payload } catch {}
  if ($o -and $o.ok -and $o.image_url) { "  " + $i + "/" + $jobs.Count + "  " + $j.n + "  ->  " + $o.image_url + "  (`$" + $o.cost_usd + ")"; $done += ($j.n + "=" + $o.image_url) }
  else { "  " + $i + "/" + $jobs.Count + "  " + $j.n + "  ->  NOT DRAWN: " + ($(if ($o) { $o.error } else { "no answer" })); $bad += $j.n }
}
"== " + $done.Count + " drawn, " + $bad.Count + " not drawn - " + [int]((Get-Date) - $t0).TotalMinutes + " min =="
if ($bad.Count) { "== not drawn: " + ($bad -join ", ") }
"== send me everything above this line =="
